        if (actual == null)
            return;
        actual.serializedObject.Update();
        actual = FindActualProperty(binding);
        if (actual == null)
            return;
        var historyIndex = FindUndoHistoryIndex(binding, undoGroup);
        if (historyIndex >= 0) {
            var record = binding.UndoHistory[historyIndex];
            binding.UndoHistoryIndex = isRedo ? historyIndex + 1 : historyIndex;
            var payload = isRedo ? record.AfterPayload : record.BeforePayload;
            if (payload != null) {
                binding.ApplyingUserChange = true;
                try {
                    ApplyUndoPayload(actual, payload);
                } finally {
                    binding.ApplyingUserChange = false;
                }
            }
        }
        if (!TryRefreshExistingPreview(binding, actual))
            RefreshPreviewFromActual(binding);
        CapturePayloadSnapshot(binding);
    }

    void CommitPreviewValue(VisualTreeBinding binding) {
        if (binding == null || binding.PreviewSerializedObject == null || binding.Property == null)
            return;
        var actualProperty = FindActualProperty(binding);
        if (actualProperty == null)
            return;
        var previewPayload = FindSerializedWrapper(binding.Property);
        var unionType = ResolveUnionType(actualProperty);
        var method = unionType?.GetMethod("__SpireFromSerialized", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
        if (method == null || previewPayload == null || previewPayload.managedReferenceValue == null)
            return;
        var replacementSnapshot = SpireSerialization.SpireCloneSerializedSnapshot(previewPayload.managedReferenceValue);
        var replacement = replacementSnapshot == null ? null : method.Invoke(null, new[] { replacementSnapshot });
        if (replacement == null)
            return;
        var beforePayload = SpireSerialization.SpireCloneSerializedSnapshot(binding.PayloadSnapshot ?? previewPayload?.managedReferenceValue);
        var afterPayload = SpireSerialization.SpireCloneSerializedSnapshot(previewPayload?.managedReferenceValue);
        if (beforePayload == null || afterPayload == null)
            return;
        var currentState = CaptureVisualTreeState(binding.Property);
        var rebuildVisualTree = binding.State.KindIndex != currentState.KindIndex || binding.State.PayloadId != currentState.PayloadId || !string.Equals(binding.State.PayloadType, currentState.PayloadType, StringComparison.Ordinal);
        Undo.IncrementCurrentGroup();
        var undoGroup = Undo.GetCurrentGroup();
        RecordRuntimeProperty(actualProperty);
        FlushPendingActualChanges(binding, actualProperty);
        actualProperty.serializedObject.Update();
        actualProperty = FindActualProperty(binding);
        if (actualProperty == null)
            return;
        SetRuntimePropertyValue(actualProperty, replacement);
        actualProperty.boxedValue = replacement;
        SetKindFromRuntimeValue(actualProperty, replacement);
        actualProperty.serializedObject.ApplyModifiedPropertiesWithoutUndo();
        actualProperty.serializedObject.Update();
        FinishPreviewCommit(binding, afterPayload, rebuildVisualTree);
        RecordUndoHistory(binding, beforePayload, afterPayload, undoGroup);
        Undo.FlushUndoRecordObjects();
    }

    void CommitMultiObjectChange(SerializedObject serialized, string rootPath, string propertyPath, string relativePath, object? value) {
        var root = serialized.FindProperty(rootPath);
        if (root == null)
            return;
        var unionType = ResolveUnionType(root);
        var method = unionType?.GetMethod("__SpireFromSerialized", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
        if (method == null)
            return;
        Undo.IncrementCurrentGroup();
        foreach (var target in serialized.targetObjects) {
            if (target == null)
                continue;
            var targetSerialized = new SerializedObject(target);
            targetSerialized.Update();
            var property = targetSerialized.FindProperty(rootPath);
            if (property == null)
                continue;
            var payload = FindSerializedWrapper(property);
            if (payload == null || payload.propertyType != SerializedPropertyType.ManagedReference || payload.managedReferenceValue == null)
                continue;
            RecordRuntimeProperty(property);
            EnsureIsolatedPayload(property, false);
            property = targetSerialized.FindProperty(rootPath);
            payload = property == null ? null : FindSerializedWrapper(property);
            if (property == null || payload == null || payload.managedReferenceValue == null)
                continue;
            var targetChangedProperty = targetSerialized.FindProperty(propertyPath);
            if (targetChangedProperty == null)
                continue;
            if (!TryConvertUserValue(targetChangedProperty, payload.managedReferenceValue, relativePath, value, out var convertedValue))
                continue;
            if (!SetRuntimePathValue(payload.managedReferenceValue, "value." + relativePath, convertedValue))
                continue;
            SetSerializedPropertyValue(targetChangedProperty, convertedValue);
            var replacement = method.Invoke(null, new[] { payload.managedReferenceValue });
            if (replacement == null)
                continue;
            SetRuntimePropertyValue(property, replacement);
            property.boxedValue = replacement;
            SetKindFromRuntimeValue(property, replacement);
            targetSerialized.ApplyModifiedPropertiesWithoutUndo();
        }
        serialized.Update();
        Undo.FlushUndoRecordObjects();
    }

    object? ReadSerializedPropertyValue(SerializedProperty property) {
        if (property == null)
            return null;
        switch (property.propertyType) {
            case SerializedPropertyType.String:
                return property.stringValue;
            case SerializedPropertyType.Integer:
                return property.intValue;
            case SerializedPropertyType.Boolean:
                return property.boolValue;
            case SerializedPropertyType.Float:
                return property.floatValue;
            case SerializedPropertyType.ObjectReference:
                return property.objectReferenceValue;
            case SerializedPropertyType.Enum:
                return property.enumValueIndex;
            case SerializedPropertyType.ManagedReference:
                return property.managedReferenceValue;
        }
        try {
            return property.boxedValue;
        } catch (InvalidOperationException) {
            return null;
        }
    }

    void SetSerializedPropertyValue(SerializedProperty? property, object? value) {
        if (property == null)
            return;
        if (property.propertyType == SerializedPropertyType.String) {
            property.stringValue = value as string ?? string.Empty;
            return;
        }
        if (property.propertyType == SerializedPropertyType.Integer) {
            if (value is long longValue)
                property.longValue = longValue;
            else if (value is int intValue)
                property.intValue = intValue;
            else
                return;
            return;
        }
        if (property.propertyType == SerializedPropertyType.Float) {
            if (value is double doubleValue)
                property.doubleValue = doubleValue;
            else if (value is float floatValue)
                property.floatValue = floatValue;
            else
                return;
            return;
        }
        if (property.propertyType == SerializedPropertyType.Enum) {
            if (!(value is Enum enumValue))
                return;
            try {
                property.enumValueFlag = unchecked((int)Convert.ToInt64(enumValue));
            } catch (OverflowException) {
                return;
            }
            return;
        }
        try {
            property.boxedValue = value;
        } catch (InvalidOperationException) {
            return;
        }
    }

    bool TryConvertUserValue(SerializedProperty property, object? payload, string relativePath, object? value, out object? convertedValue) {
        convertedValue = value;
        if (property == null || property.propertyType != SerializedPropertyType.Enum)
            return true;
        var enumType = ResolvePathType(property);
        if (enumType == null || !enumType.IsEnum) {
            if (TryGetRuntimePathValue(payload, "value." + relativePath, out var current) && current != null && current.GetType().IsEnum)
                enumType = current.GetType();
        }
        if (enumType == null || !enumType.IsEnum)
            return false;
        if (value is string enumText) {
            if (!TryGetEnumMemberNames(property, enumText, out var memberNames))
                return false;
            try {
                convertedValue = Enum.Parse(enumType, memberNames, true);
                return true;
            } catch (ArgumentException) {
                return false;
            }
        }
        if (value is int enumIndex) {
            var enumNames = property.enumNames;
            if (enumNames != null && enumIndex >= 0 && enumIndex < enumNames.Length) {
                try {
                    convertedValue = Enum.Parse(enumType, enumNames[enumIndex], false);
                    return true;
                } catch (ArgumentException) {
                    return false;
                }
            }
            return false;
        }
        if (value is Enum enumValue) {
            if (enumValue.GetType() == enumType)
                return true;
            convertedValue = Enum.ToObject(enumType, Convert.ToInt64(enumValue));
            return true;
        }
        return value == null;
    }

    bool TryGetEnumMemberNames(SerializedProperty property, string text, out string memberNames) {
        memberNames = string.Empty;
        if (property == null || string.IsNullOrWhiteSpace(text))
            return false;
        var enumNames = property.enumNames ?? Array.Empty<string>();
        var enumDisplayNames = property.enumDisplayNames ?? Array.Empty<string>();
        for (var index = 0; index < enumNames.Length; index++) {
            var displayName = index < enumDisplayNames.Length ? enumDisplayNames[index] : string.Empty;
            if (string.Equals(enumNames[index], text, StringComparison.Ordinal) || string.Equals(displayName, text, StringComparison.Ordinal)) {
                memberNames = enumNames[index];
                return true;
            }
        }
        return false;
    }

    sealed class VisualTreeBinding {
        public readonly __SpireUnityPropertyDrawer Owner;
        public readonly VisualElement Root;
        public SerializedProperty Property;
        public string PropertyPath;
        public readonly SerializedObject ActualSerializedObject;
        public readonly string ActualPropertyPath;
        public UnityEngine.Object? PreviewTarget;
        public SerializedObject? PreviewSerializedObject;
        public readonly bool IsNestedPreviewBinding;
        public object? PayloadSnapshot;
        public readonly List<UndoPayloadRecord> UndoHistory = new List<UndoPayloadRecord>();
        public int UndoHistoryIndex;
        public SerializedObject? TrackedSerializedObject;
        public SerializedObject? TrackedActualSerializedObject;
        public string TrackedPropertyPath = string.Empty;
        public int TrackingGeneration;
        public int VisualTreeGeneration;
        public bool UndoTrackingAttached;
        public bool UndoRefreshPending;
        public bool ActualPollingAttached;
        public bool ApplyingUserChange;
        public bool SynchronizingRuntimeValue;
        public readonly HashSet<Type> RegisteredChangeTypes = new HashSet<Type>();
        public readonly HashSet<VisualElement> RegisteredChangeElements = new HashSet<VisualElement>();
        public readonly VisualTreeState State;
        public void OnUndoRedo(in UndoRedoInfo info) => Owner.QueueUndoRefresh(this, info);
        public void OnDelayedUndoRefresh() => Owner.RefreshVisualTreeAfterUndo(this);
        public void OnDelayedControlRefresh() => Owner.RegisterChangeCallbacks(this, Root);
        public void OnActualPoll() => Owner.PollActualChange(this);

        public VisualTreeBinding(__SpireUnityPropertyDrawer owner, VisualElement root, SerializedProperty property) {
            Owner = owner;
            Root = root;
            Property = property;
            PropertyPath = property.propertyPath;
            ActualSerializedObject = property.serializedObject;
            ActualPropertyPath = property.propertyPath;
            IsNestedPreviewBinding = !ActualSerializedObject.isEditingMultipleObjects && ActualSerializedObject.targetObject != null && (ActualSerializedObject.targetObject.hideFlags & HideFlags.HideAndDontSave) != 0;
            if (!ActualSerializedObject.isEditingMultipleObjects)
                Owner.RefreshPreviewFromActual(this);
            State = Owner.CaptureVisualTreeState(property);
            Owner.CapturePayloadSnapshot(this);
            Root.RegisterCallback<SerializedObjectChangeEvent>(changed => Owner.HandleSerializedObjectChange(this, changed));
            Root.RegisterCallback<SerializedPropertyChangeEvent>(changed => Owner.HandleSerializedPropertyChange(this, changed), TrickleDown.TrickleDown);
            Root.RegisterCallback<AttachToPanelEvent>(_ => Owner.RegisterChangeCallbacks(this, Root));
            Root.RegisterCallback<AttachToPanelEvent>(_ => Owner.AttachUndoTracking(this));
            Root.RegisterCallback<DetachFromPanelEvent>(_ => Owner.DetachUndoTracking(this));
            if (Root.panel != null) Owner.AttachUndoTracking(this);
        }
    }

    void HandleSerializedObjectChange(VisualTreeBinding binding, SerializedObjectChangeEvent changed) {
        if (binding.ApplyingUserChange)
            return;
        if (binding.PreviewSerializedObject != null && ReferenceEquals(changed.changedObject, binding.ActualSerializedObject)) {
            RefreshPreviewAfterActualChange(binding);
            return;
        }
        RebuildVisualTreeIfChanged(binding, changed.changedObject);
    }

    void HandleSerializedPropertyChange(VisualTreeBinding binding, SerializedPropertyChangeEvent changed) {
        if (binding.ApplyingUserChange)
            return;
        if (binding.PreviewSerializedObject != null && changed.changedProperty != null && ReferenceEquals(changed.changedProperty.serializedObject, binding.PreviewSerializedObject)) {
            var previousState = CaptureVisualTreeState(binding.Property);
            RebuildVisualTreeIfChanged(binding, changed.changedProperty);
            var currentState = CaptureVisualTreeState(binding.Property);
            var previewPayload = FindSerializedWrapper(binding.Property);
            var payloadChanged = previewPayload != null && previewPayload.managedReferenceValue != null && binding.PayloadSnapshot != null && !SpireSerialization.SpireSerializedValuesEqual(previewPayload.managedReferenceValue, binding.PayloadSnapshot);
            var nestedGenericChanged = changed.changedProperty.propertyType == SerializedPropertyType.Generic && changed.changedProperty.propertyPath.StartsWith(binding.PropertyPath + ".", StringComparison.Ordinal);
            if (previousState.KindIndex != currentState.KindIndex || previousState.PayloadId != currentState.PayloadId || !string.Equals(previousState.PayloadType, currentState.PayloadType, StringComparison.Ordinal) || payloadChanged || nestedGenericChanged) {
                binding.ApplyingUserChange = true;
                try {
                    CommitPreviewValue(binding);
                } finally {
                    binding.ApplyingUserChange = false;
                }
            }
            return;
        }
        if (binding.PreviewSerializedObject != null && changed.changedProperty != null && ReferenceEquals(changed.changedProperty.serializedObject, binding.ActualSerializedObject)) {
            RefreshPreviewAfterActualChange(binding);
            return;
        }
        SynchronizeRuntimeValue(binding, changed.changedProperty);
        RebuildVisualTreeIfChanged(binding, changed.changedProperty);
    }

    void RefreshPreviewAfterActualChange(VisualTreeBinding binding) {
        var actual = FindActualProperty(binding);
        if (actual == null)
            return;
        if (ActualPayloadMatchesSnapshot(binding, actual) && KindMatchesPreview(binding, actual))
            return;
        var actualState = CaptureVisualTreeState(actual);
        if (TryRefreshExistingPreview(binding, actual) &&
            binding.State.KindIndex == actualState.KindIndex &&
            string.Equals(binding.State.PayloadType, actualState.PayloadType, StringComparison.Ordinal)) {
            CapturePayloadSnapshot(binding);
            return;
        }
        RefreshPreviewFromActual(binding);
        CapturePayloadSnapshot(binding);
        RebuildVisualTreeIfChanged(binding, binding.Property);
    }

    void AttachUndoTracking(VisualTreeBinding binding) {
        if (binding.UndoTrackingAttached)
            return;
        Undo.undoRedoEvent += binding.OnUndoRedo;
        if (binding.PreviewSerializedObject != null && !binding.ActualPollingAttached) {
            EditorApplication.update += binding.OnActualPoll;
            binding.ActualPollingAttached = true;
        }
        binding.UndoTrackingAttached = true;
        RefreshVisualTreeOnAttach(binding);
        EditorApplication.delayCall += binding.OnDelayedControlRefresh;
    }

    void RefreshVisualTreeOnAttach(VisualTreeBinding binding) {
        if (binding.Root.panel == null)
            return;
        RefreshPreviewFromActual(binding);
        if (binding.Property == null)
            return;
        var serialized = binding.Property.serializedObject;
        serialized.Update();
        var property = serialized.FindProperty(binding.PropertyPath);
        if (property == null)
            return;
        binding.Property = property;
        CapturePayloadSnapshot(binding);
        var current = CaptureVisualTreeState(property);
        binding.State.KindIndex = current.KindIndex;
        binding.State.PayloadId = current.PayloadId;
        binding.State.PayloadType = current.PayloadType;
        RebuildVisualTree(binding);
    }

    void DetachUndoTracking(VisualTreeBinding binding) {
        if (!binding.UndoTrackingAttached)
            return;
        Undo.undoRedoEvent -= binding.OnUndoRedo;
        if (binding.ActualPollingAttached) {
            EditorApplication.update -= binding.OnActualPoll;
            binding.ActualPollingAttached = false;
        }
        EditorApplication.delayCall -= binding.OnDelayedUndoRefresh;
        EditorApplication.delayCall -= binding.OnDelayedControlRefresh;
        DestroyPreview(binding);
        binding.UndoTrackingAttached = false;
        binding.UndoRefreshPending = false;
    }

    void RefreshVisualTreeAfterUndo(VisualTreeBinding binding) {
        binding.UndoRefreshPending = true;
        binding.ApplyingUserChange = true;
        try {
            if (!binding.UndoTrackingAttached || binding.Root.panel == null)
                return;
            var actual = FindActualProperty(binding);
            if (actual == null)
                return;
            actual.serializedObject.Update();
            var previousKind = binding.State.KindIndex;
            var previousPayloadType = binding.State.PayloadType;
            var keptExistingPreview = TryRefreshExistingPreview(binding, actual);
            if (keptExistingPreview) {
                var previewState = CaptureVisualTreeState(binding.Property);
                if (previousKind == previewState.KindIndex &&
                    string.Equals(previousPayloadType, previewState.PayloadType, StringComparison.Ordinal)) {
                    binding.State.KindIndex = previewState.KindIndex;
                    binding.State.PayloadId = previewState.PayloadId;
                    binding.State.PayloadType = previewState.PayloadType;
                    CapturePayloadSnapshot(binding);
                    return;
                }
            }
            binding.Root.Unbind();
            RefreshPreviewFromActual(binding);
            if (binding.Property == null)
                return;
            var serialized = binding.Property.serializedObject;
            serialized.Update();
            var property = serialized.FindProperty(binding.PropertyPath);
            if (property == null)
                return;
            binding.Property = property;
            CapturePayloadSnapshot(binding);
            var current = CaptureVisualTreeState(property);
            binding.State.KindIndex = current.KindIndex;
            binding.State.PayloadId = current.PayloadId;
            binding.State.PayloadType = current.PayloadType;
            RebuildVisualTree(binding);
        } finally {
            binding.ApplyingUserChange = false;
            binding.UndoRefreshPending = false;
        }
    }

    void QueueUndoRefresh(VisualTreeBinding binding, in UndoRedoInfo info) {
        if (!binding.UndoTrackingAttached || binding.Root.panel == null)
            return;
        ProcessUndoRedo(binding, info.undoGroup, info.isRedo);
        if (binding.UndoRefreshPending)
            return;
        binding.UndoRefreshPending = true;
        EditorApplication.delayCall += binding.OnDelayedUndoRefresh;
    }

    void PollActualChange(VisualTreeBinding binding) {
        if (binding == null || binding.ApplyingUserChange || binding.PreviewSerializedObject == null ||
            binding.ActualSerializedObject == null || binding.ActualSerializedObject.isEditingMultipleObjects ||
            binding.Root.panel == null)
            return;
        binding.ActualSerializedObject.Update();
        RefreshPreviewAfterActualChange(binding);
    }

    void AttachVisualTreeTracking(VisualTreeBinding binding, bool force) {
        if (binding == null || binding.Property == null)
            return;
        var property = binding.Property;
        var serialized = property.serializedObject;
        if (!force && ReferenceEquals(binding.TrackedSerializedObject, serialized) && string.Equals(binding.TrackedPropertyPath, property.propertyPath, StringComparison.Ordinal))
            return;
        binding.TrackedSerializedObject = serialized;
        binding.TrackedPropertyPath = property.propertyPath;
        if (binding.PreviewSerializedObject != null) {
            if (!ReferenceEquals(binding.TrackedActualSerializedObject, binding.ActualSerializedObject)) {
                binding.TrackedActualSerializedObject = binding.ActualSerializedObject;
                var actualGeneration = ++binding.TrackingGeneration;
                binding.Root.TrackSerializedObjectValue(binding.ActualSerializedObject, changed => {
                    if (binding.TrackingGeneration == actualGeneration)
                        RefreshPreviewAfterActualChange(binding);
                });
            }
            return;
        }
        var generation = ++binding.TrackingGeneration;
        binding.Root.TrackPropertyValue(property, changed => { if (binding.TrackingGeneration == generation) { SynchronizeRuntimeValue(binding, changed); RebuildVisualTreeIfChanged(binding, changed); } });
        binding.Root.TrackSerializedObjectValue(serialized, changed => { if (binding.TrackingGeneration == generation) RebuildVisualTreeIfChanged(binding, changed); });
    }

    VisualTreeState CaptureVisualTreeState(SerializedProperty property) {
        var payload = FindSerializedWrapper(property);
        return new VisualTreeState {
            KindIndex = ReadKindIndex(property),
            PayloadId = payload == null ? 0L : payload.managedReferenceId,
            PayloadType = payload == null ? string.Empty : payload.managedReferenceFullTypename ?? string.Empty,
        };
    }

    bool KindMatchesPreview(VisualTreeBinding binding, SerializedProperty actual) {
        if (binding is null || binding.Property is null || actual is null)
            return false;
        return ReadKindIndex(binding.Property) == ReadKindIndex(actual);
    }

    void FinishPreviewCommit(VisualTreeBinding binding, object? afterPayload, bool rebuildVisualTree) {
        if (binding == null || afterPayload == null)
            return;
        binding.PayloadSnapshot = SpireSerialization.SpireCloneSerializedSnapshot(afterPayload);
        var actual = FindActualProperty(binding);
        var actualMatches = actual != null && ActualPayloadMatchesSnapshot(binding, actual);
        if (!rebuildVisualTree) {
            if (actualMatches)
                return;
        }
        RefreshPreviewFromActual(binding);
        if (binding.Property == null)
            return;
        var current = CaptureVisualTreeState(binding.Property);
        binding.State.KindIndex = current.KindIndex;
        binding.State.PayloadId = current.PayloadId;
        binding.State.PayloadType = current.PayloadType;
        RebuildVisualTree(binding);
    }

    void RebuildVisualTreeIfChanged(VisualTreeBinding binding, SerializedProperty? changed) {
        if (binding == null || binding.Property == null || changed == null)
            return;
        if (!TryUpdateBinding(binding, changed))
            return;
        var serializedObjectChanged = !ReferenceEquals(binding.TrackedSerializedObject, binding.Property.serializedObject);
        var current = CaptureVisualTreeState(binding.Property);
        var payload = FindPayload(binding.Property);
        var isPreviewLeafChange =
            ReferenceEquals(changed.serializedObject, binding.PreviewSerializedObject) &&
            !serializedObjectChanged &&
            payload != null &&
            changed.propertyPath.StartsWith(payload.propertyPath + ".", StringComparison.Ordinal);
        if (isPreviewLeafChange &&
            binding.State.KindIndex == current.KindIndex &&
            string.Equals(binding.State.PayloadType, current.PayloadType, StringComparison.Ordinal)) {
            binding.State.PayloadId = current.PayloadId;
            return;
        }
        if (binding.State.KindIndex == current.KindIndex && binding.State.PayloadId == current.PayloadId && string.Equals(binding.State.PayloadType, current.PayloadType, StringComparison.Ordinal)) {
            if (serializedObjectChanged && !binding.UndoRefreshPending)
                RebuildVisualTree(binding);
            return;
        }
        binding.State.KindIndex = current.KindIndex;
        binding.State.PayloadId = current.PayloadId;
        binding.State.PayloadType = current.PayloadType;
        RebuildVisualTree(binding);
    }

    void RebuildVisualTreeIfChanged(VisualTreeBinding binding, SerializedObject changed) {
        if (binding == null || binding.Property == null || changed == null)
            return;
        var property = changed.FindProperty(binding.PropertyPath);
        if (property == null)
            return;
        binding.Property = property;
        var serializedObjectChanged = !ReferenceEquals(binding.TrackedSerializedObject, changed);
        var current = CaptureVisualTreeState(property);
        if (binding.State.KindIndex == current.KindIndex && binding.State.PayloadId == current.PayloadId && string.Equals(binding.State.PayloadType, current.PayloadType, StringComparison.Ordinal)) {
            if (serializedObjectChanged && !binding.UndoRefreshPending)
                RebuildVisualTree(binding);
            return;
        }
        binding.State.KindIndex = current.KindIndex;
        binding.State.PayloadId = current.PayloadId;
        binding.State.PayloadType = current.PayloadType;
        RebuildVisualTree(binding);
    }

    bool TryUpdateBinding(VisualTreeBinding binding, SerializedProperty changed) {
        var changedPath = changed.propertyPath;
        var payloadSuffix = "." + PayloadFieldName;
        var propertyPath = binding.PropertyPath;
        var isDescendant = changedPath.StartsWith(binding.PropertyPath + ".", StringComparison.Ordinal);
        var payloadIndex = changedPath.LastIndexOf(payloadSuffix, StringComparison.Ordinal);
        var isSameProperty = string.Equals(changedPath, binding.PropertyPath, StringComparison.Ordinal);
        if (!isSameProperty && !isDescendant && payloadIndex >= 0)
            propertyPath = changedPath.Substring(0, payloadIndex);
        else if (!isSameProperty && !isDescendant)
            return false;
        var property = changed.serializedObject.FindProperty(propertyPath);
        if (property == null)
            return false;
        binding.PropertyPath = propertyPath;
        binding.Property = property;
        return true;
    }

    void RebuildVisualTree(VisualTreeBinding binding) {
        if (binding == null || binding.Property == null)
            return;
        var root = binding.Root;
        var generation = ++binding.VisualTreeGeneration;
        binding.RegisteredChangeTypes.Clear();
        binding.RegisteredChangeElements.Clear();
        root.Unbind();
        root.Clear();
        AttachVisualTreeTracking(binding, true);
        var property = binding.Property;
        binding.Property = property;
        var currentState = CaptureVisualTreeState(property);
        binding.State.KindIndex = currentState.KindIndex;
        binding.State.PayloadId = currentState.PayloadId;
        binding.State.PayloadType = currentState.PayloadType;
        var payload = FindPayload(property);
        var index = currentState.KindIndex;
        var kindType = ResolveKindType(FindActualProperty(binding) ?? property);
        if (kindType is not null && kindType.IsEnum) {
            var enumValue = (Enum)Enum.ToObject(kindType, index >= 0 ? index : 0);
            var enumField = new EnumField("Variant", enumValue) {
                showMixedValue = index == MixedKindIndex,
            };
            enumField.RegisterValueChangedCallback(change => {
                if (generation != binding.VisualTreeGeneration || enumField.parent != root)
                    return;
                var selected = Convert.ToInt32(change.newValue);
                if (selected < 0 || selected >= Metadata.Variants.Count)
                    return;
                CommitKindSelection(binding, selected);
            });
            root.Add(enumField);
        } else {
            var choices = new List<string>(Metadata.Variants.Count);
            foreach (var variant in Metadata.Variants)
                choices.Add(variant.Ident);
            var popup = new PopupField<string>(choices, index >= 0 ? index : 0) {
                label = "Variant",
            };
            if (index == MixedKindIndex)
                popup.showMixedValue = true;
            popup.RegisterValueChangedCallback(change => {
                if (generation != binding.VisualTreeGeneration || popup.parent != root)
                    return;
                var selected = choices.IndexOf(change.newValue);
                if (selected < 0)
                    return;
                CommitKindSelection(binding, selected);
            });
            root.Add(popup);
        }
        if (index < 0 || index >= Metadata.Variants.Count)
            return;
        if (payload == null)
            return;
        var payloadField = new PropertyField(payload, payload.displayName);
        payloadField.Bind(property.serializedObject);
        root.Add(payloadField);
        RegisterChangeCallbacks(binding, root);
        if (root.panel != null) EditorApplication.delayCall += binding.OnDelayedControlRefresh;
        CapturePayloadSnapshot(binding);
    }

    void CommitKindSelection(VisualTreeBinding binding, int selected) {
        if (binding == null || binding.Property == null)
            return;

        if (binding.PreviewSerializedObject != null) {
            var previewProperty = binding.PreviewSerializedObject.FindProperty(binding.PropertyPath);
            var actualProperty = FindActualProperty(binding);
            if (previewProperty == null || actualProperty == null)
                return;
            binding.ApplyingUserChange = true;
            try {
                ReplaceWithVariant(previewProperty, selected, false, ResolveUnionType(actualProperty));
                binding.Property = binding.PreviewSerializedObject.FindProperty(binding.PropertyPath) ?? previewProperty;
                CommitPreviewValue(binding);
            } finally {
                binding.ApplyingUserChange = false;
            }
            return;
        }

        var actual = FindActualProperty(binding) ?? binding.Property;
        if (actual == null)
            return;

        Undo.IncrementCurrentGroup();
        RecordRuntimeProperty(actual);
        ReplaceWithVariant(actual, selected, false, ResolveUnionType(actual));
        actual.serializedObject.Update();
        actual = actual.serializedObject.FindProperty(actual.propertyPath) ?? actual;
        SynchronizeRuntimeValueAfterSerializedReplacement(actual);
        binding.Property = actual;
        binding.State.KindIndex = ReadKindIndex(actual);
        var state = CaptureVisualTreeState(actual);
        binding.State.KindIndex = state.KindIndex;
        binding.State.PayloadId = state.PayloadId;
        binding.State.PayloadType = state.PayloadType;
        RebuildVisualTree(binding);
        Undo.FlushUndoRecordObjects();
    }

    void SynchronizeRuntimeValueAfterSerializedReplacement(SerializedProperty property) {
        if (property == null)
            return;
        var serialized = property.serializedObject;
        var propertyPath = property.propertyPath;
        foreach (var target in serialized.targetObjects) {
            if (target == null)
                continue;
            var targetSerialized = new SerializedObject(target);
            targetSerialized.Update();
            var targetProperty = targetSerialized.FindProperty(propertyPath);
            if (targetProperty == null)
                continue;
            var payload = FindSerializedWrapper(targetProperty);
            if (payload == null || payload.managedReferenceValue == null)
                continue;
            var unionType = ResolveUnionType(targetProperty);
            var method = unionType?.GetMethod("__SpireFromSerialized", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
            if (method == null)
                continue;
            var snapshot = SpireSerialization.SpireCloneSerializedSnapshot(payload.managedReferenceValue);
            var replacement = snapshot == null ? null : method.Invoke(null, new[] { snapshot });
            if (replacement == null)
                continue;
            SetRuntimePathValue(target, propertyPath, replacement);
            targetProperty.boxedValue = replacement;
            SetKindFromRuntimeValue(targetProperty, replacement);
            targetSerialized.ApplyModifiedPropertiesWithoutUndo();
        }
        serialized.Update();
    }

    bool IsSupportedChangeProperty(SerializedProperty property, Type valueType) {
        if (property == null || valueType == null)
            return false;
        switch (property.propertyType) {
            case SerializedPropertyType.String:
                return valueType == typeof(string);
            case SerializedPropertyType.Boolean:
                return valueType == typeof(bool);
            case SerializedPropertyType.Integer:
                return valueType == typeof(int) || valueType == typeof(long) || valueType == typeof(short) || valueType == typeof(byte) || valueType == typeof(uint) || valueType == typeof(ulong) || valueType == typeof(ushort) || valueType == typeof(sbyte);
            case SerializedPropertyType.Float:
                return valueType == typeof(float) || valueType == typeof(double);
            case SerializedPropertyType.Enum:
                return valueType.IsEnum || valueType == typeof(Enum) || valueType == typeof(int) || valueType == typeof(string);
            case SerializedPropertyType.ObjectReference:
                return typeof(UnityEngine.Object).IsAssignableFrom(valueType);
            default:
                return false;
        }
    }

    void RegisterChangeCallbacks(VisualTreeBinding binding, VisualElement root) {
        if (binding == null || root == null)
            return;
        if (binding.IsNestedPreviewBinding)
            return;
        RegisterChangeCallback(binding, root);
        root.Query<VisualElement>().ForEach(element => RegisterChangeCallback(binding, element));
    }

    void RegisterChangeCallback(VisualTreeBinding binding, VisualElement element) {
        if (binding == null || element == null || binding.RegisteredChangeElements.Contains(element))
            return;
        var bindable = element as IBindable;
        if (bindable == null || string.IsNullOrEmpty(bindable.bindingPath))
            return;
        var valueProperty = element.GetType().GetProperty("value", BindingFlags.Instance | BindingFlags.Public);
        if (valueProperty == null || !valueProperty.CanRead || valueProperty.PropertyType.IsByRef || valueProperty.PropertyType.IsPointer || valueProperty.PropertyType.ContainsGenericParameters)
            return;
        if (!TryResolveChangeProperty(binding, element, bindable.bindingPath, out var resolvedProperty, out _, out _))
            return;
        if (resolvedProperty == null)
            return;
        if (!IsSupportedChangeProperty(resolvedProperty, valueProperty.PropertyType))
            return;
        var register = typeof(global::Houtamelo.Spire.Generated.__SpireUnityPropertyDrawer).GetMethod("RegisterChangeCallbackForType", BindingFlags.Instance | BindingFlags.NonPublic);
        if (register == null)
            return;
        var payloadMarker = PayloadFieldName + ".";
        var payloadMarkerIndex = bindable.bindingPath.LastIndexOf(payloadMarker, StringComparison.Ordinal);
        var nestedPayloadField = payloadMarkerIndex >= 0 && bindable.bindingPath.Substring(payloadMarkerIndex + payloadMarker.Length).IndexOf(".", StringComparison.Ordinal) >= 0;
        for (var ancestor = element.parent; ancestor != null; ancestor = ancestor.parent) {
            var ancestorBindable = ancestor as IBindable;
            if (ancestorBindable != null && !string.IsNullOrEmpty(ancestorBindable.bindingPath) && !string.Equals(ancestorBindable.bindingPath, bindable.bindingPath, StringComparison.Ordinal)) {
                nestedPayloadField = true;
                break;
            }
        }
        register.MakeGenericMethod(valueProperty.PropertyType).Invoke(this, new object[] { binding, element, nestedPayloadField });
        binding.RegisteredChangeTypes.Add(valueProperty.PropertyType);
        binding.RegisteredChangeElements.Add(element);
    }

    void RegisterChangeCallbackForType<T>(VisualTreeBinding binding, VisualElement element, bool registerOnElement) {
        if (binding.RegisteredChangeTypes.Add(typeof(T)))
            binding.Root.RegisterCallback<ChangeEvent<T>>(changed => ApplyUserChange(binding, changed), TrickleDown.TrickleDown);
        if (registerOnElement)
            element.RegisterCallback<ChangeEvent<T>>(changed => ApplyUserChange(binding, changed), TrickleDown.TrickleDown);
    }

    SerializedProperty? FindSerializedWrapper(SerializedProperty property) {
        if (property == null)
            return null;
        var nested = property.FindPropertyRelative(PayloadFieldName);
        if (nested != null)
            return nested;
        return property.propertyType == SerializedPropertyType.ManagedReference && property.managedReferenceValue is PayloadBase ? property : null;
    }

    SerializedProperty? FindPayload(SerializedProperty property) {
        var wrapper = FindSerializedWrapper(property);
        if (wrapper is null)
            return null;
        return wrapper.FindPropertyRelative("value");
    }

    SerializedProperty? FindKindProperty(SerializedProperty property) {
        if (property == null)
            return null;
        return property.FindPropertyRelative(KindFieldName) ??
            property.FindPropertyRelative("KindIndex");
    }

    int ReadKindIndex(SerializedProperty? property) {
        var kind = property is null ? null : FindKindProperty(property);
        if (kind is null) {
            var payloadIndex = ReadPayloadTypeIndex(property);
            return payloadIndex >= 0
                ? payloadIndex
                : Metadata.Variants.Count == 0 ? InvalidKindIndex : 0;
        }
        if (kind.hasMultipleDifferentValues)
            return MixedKindIndex;
        var index = kind.propertyType == SerializedPropertyType.Enum
            ? kind.enumValueIndex
            : kind.propertyType == SerializedPropertyType.Integer
                ? kind.intValue
                : InvalidKindIndex;
        if (index >= 0 && index < Metadata.Variants.Count)
            return index;
        var payloadTypeIndex = ReadPayloadTypeIndex(property);
        return payloadTypeIndex >= 0
            ? payloadTypeIndex
            : Metadata.Variants.Count == 0 ? InvalidKindIndex : 0;
    }

    int ReadPayloadTypeIndex(SerializedProperty? property) {
        var wrapper = property is null ? null : FindSerializedWrapper(property);
        var value = wrapper?.managedReferenceValue;
        if (value is null)
            return -1;
        var type = value.GetType();
        var genericArguments = type.IsGenericType ? type.GetGenericArguments() : Type.EmptyTypes;
        var payloadType = genericArguments.Length == 1
            ? genericArguments[0]
            : null;
        var fullName = payloadType?.FullName ?? payloadType?.Name ?? string.Empty;
        if (fullName.Length == 0)
            return -1;
        for (var index = 0; index < Metadata.Variants.Count; index++) {
            var variant = Metadata.Variants[index];
            if (IsPayloadTypeName(fullName, variant.PayloadType) ||
                (variant.PayloadTypeAlias is not null &&
                    IsPayloadTypeName(fullName, variant.PayloadTypeAlias)))
                return index;
        }
        return -1;
    }

    bool IsPayloadTypeName(string typeName, string payloadName) {
        foreach (var separator in new[] { "/", "+", "." }) {
            var marker = separator + payloadName;
            var start = typeName.LastIndexOf(marker, StringComparison.Ordinal);
            if (start < 0)
                continue;
            var end = start + marker.Length;
            if (end == typeName.Length || typeName[end] is '`' or '[')
                return true;
        }
        return string.Equals(typeName, payloadName, StringComparison.Ordinal) ||
            typeName.StartsWith(payloadName + "`", StringComparison.Ordinal);
    }

    void SetKindIndex(SerializedProperty property, int index) {
        var kind = FindKindProperty(property);
        if (kind is null || index < 0)
            return;
        if (kind.propertyType == SerializedPropertyType.Enum)
            kind.enumValueIndex = index;
        else if (kind.propertyType == SerializedPropertyType.Integer)
            kind.intValue = index;
    }

    void SetKindFromRuntimeValue(SerializedProperty property, object value) {
        if (property is null || value is null)
            return;
        var kind = value.GetType().GetProperty(
            "kind",
            BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
        if (kind is null)
            return;
        var kindValue = kind.GetValue(value);
        if (kindValue is null)
            return;
        try {
            SetKindIndex(property, Convert.ToInt32(kindValue));
        } catch (InvalidCastException) {
            return;
        } catch (FormatException) {
            return;
        } catch (OverflowException) {
            return;
        }
    }

    void ApplyUserChange<T>(VisualTreeBinding binding, ChangeEvent<T> changed) {
        if (binding == null || changed == null)
            return;
        var bindable = changed.target as IBindable;
        if (bindable == null || string.IsNullOrEmpty(bindable.bindingPath))
            return;
        if (binding.ApplyingUserChange) {
            changed.StopImmediatePropagation();
            (changed.target as VisualElement)?.focusController?.IgnoreEvent(changed);
            return;
        }
        if (!TryResolveChangeProperty(binding, changed.target as VisualElement, bindable.bindingPath, out var resolvedProperty, out var resolvedPath, out _)) {
            return;
        }
        if (resolvedProperty == null) {
            return;
        }
        if (!IsSupportedChangeProperty(resolvedProperty, typeof(T))) {
            return;
        }
        var isUserChange = IsUserChange(binding, resolvedProperty, resolvedPath, changed.newValue);
        if (!isUserChange) {
            changed.StopImmediatePropagation();
            (changed.target as VisualElement)?.focusController?.IgnoreEvent(changed);
            return;
        }
        changed.StopImmediatePropagation();
        (changed.target as VisualElement)?.focusController?.IgnoreEvent(changed);
        binding.ApplyingUserChange = true;
        try {
            CommitUserChange(binding, resolvedPath, changed.newValue);
        } finally {
            binding.ApplyingUserChange = false;
        }
    }

    bool IsUserChange<T>(VisualTreeBinding binding, SerializedProperty? property, string path, T value) {
        if (!TryResolveChangeProperty(binding, path, out _, out _, out var relativePath))
            return false;
        object? comparableValue = value;
        var payload = binding.PayloadSnapshot;
        if (payload == null) {
            var currentPayload = FindSerializedWrapper(binding.Property);
            payload = currentPayload == null ? null : currentPayload.managedReferenceValue;
        }
        if (property != null && payload != null && !TryConvertUserValue(property, payload, relativePath, value, out comparableValue))
            return true;
        if (binding.PayloadSnapshot != null && TryGetRuntimePathValue(binding.PayloadSnapshot, "value." + relativePath, out var snapshotValue))
            return !Equals(snapshotValue, comparableValue);
        var target = binding.Property.serializedObject.targetObject;
        if (target == null)
            return true;
        if (!TryGetRuntimePathValue(target, binding.PropertyPath, out var runtimeRoot))
            return true;
        if (!TryGetRuntimePathValue(runtimeRoot, relativePath, out var runtimeValue))
            return true;
        return !Equals(runtimeValue, comparableValue);
    }

    void EnsureIsolatedPayload(SerializedProperty property, bool recordUndo) {
        if (property == null || property.serializedObject.isEditingMultipleObjects)
            return;
        var payload = FindSerializedWrapper(property);
        if (payload == null || payload.propertyType != SerializedPropertyType.ManagedReference || payload.managedReferenceValue == null)
            return;
        if (!HasSharedManagedReference(payload))
            return;
        var snapshot = SpireSerialization.SpireCloneSerializedSnapshot(payload.managedReferenceValue);
        if (snapshot == null)
            return;
        var unionType = ResolveUnionType(property);
        if (unionType == null)
            return;
        var method = unionType.GetMethod("__SpireFromSerialized", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
        if (method == null)
            return;
        var replacement = method.Invoke(null, new[] { snapshot });
        if (replacement == null)
            return;
        if (recordUndo)
            RecordRuntimeProperty(property);
        SetRuntimePropertyValue(property, replacement);
        property.boxedValue = replacement;
        SetKindFromRuntimeValue(property, replacement);
    }

    bool HasSharedManagedReference(SerializedProperty payload) {
        var id = payload.managedReferenceId;
        if (id == 0)
            return false;
        var iterator = payload.serializedObject.GetIterator();
        var enterChildren = true;
        while (iterator.NextVisible(enterChildren)) {
            enterChildren = iterator.hasVisibleChildren;
            if (iterator.propertyType == SerializedPropertyType.ManagedReference && iterator.managedReferenceId == id && !string.Equals(iterator.propertyPath, payload.propertyPath, StringComparison.Ordinal))
                return true;
        }
        return false;
    }

    void SynchronizeRuntimeValue(VisualTreeBinding binding, SerializedProperty? changed) {
        if (binding == null || binding.SynchronizingRuntimeValue || changed == null)
            return;
        if (binding.PreviewSerializedObject != null)
            return;
        var property = changed.serializedObject.FindProperty(binding.PropertyPath);
        if (property == null)
            return;
        binding.Property = property;
        var kindPath = binding.PropertyPath + "." + KindFieldName;
        if (string.Equals(changed.propertyPath, kindPath, StringComparison.Ordinal)) {
            binding.SynchronizingRuntimeValue = true;
            try {
                var selected = ReadKindIndex(property);
                if (selected == MixedKindIndex) {
                    var kind = FindKindProperty(property);
                    selected = kind is not null && kind.propertyType == SerializedPropertyType.Enum
                        ? kind.enumValueIndex
                        : selected;
                }
                if (selected >= 0 && selected < Metadata.Variants.Count)
                    ReplaceWithVariant(property, selected);
            } finally {
                binding.SynchronizingRuntimeValue = false;
            }
            return;
        }
        if (!TryResolveChangeProperty(binding, changed.propertyPath, out _, out _, out _))
            return;
        binding.SynchronizingRuntimeValue = true;
        try {
            if (changed.serializedObject.isEditingMultipleObjects) {
                CommitUserChange(binding, changed.propertyPath, ReadSerializedPropertyValue(changed));
            } else {
                SynchronizeRuntimeValue(property);
            }
        } finally {
            binding.SynchronizingRuntimeValue = false;
        }
    }

    void SynchronizeRuntimeValue(SerializedProperty property) {
        if (property == null)
            return;
        if (!property.serializedObject.hasModifiedProperties)
            return;
        var unionType = ResolveUnionType(property);
        if (unionType == null)
            return;
        var method = unionType.GetMethod("__SpireFromSerialized", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
        if (method == null)
            return;
        if (property.serializedObject.isEditingMultipleObjects) {
            property.serializedObject.ApplyModifiedPropertiesWithoutUndo();
            property.serializedObject.Update();
            return;
        }
        var payload = FindSerializedWrapper(property);
        if (payload == null || payload.propertyType != SerializedPropertyType.ManagedReference || payload.managedReferenceValue == null)
            return;
        var replacement = method.Invoke(null, new[] { payload.managedReferenceValue });
        if (replacement == null)
            return;
        Undo.IncrementCurrentGroup();
        RecordRuntimeProperty(property);
        EnsureIsolatedPayload(property, false);
        property = property.serializedObject.FindProperty(property.propertyPath);
        payload = property == null ? null : FindSerializedWrapper(property);
        if (property == null || payload == null || payload.managedReferenceValue == null)
            return;
        replacement = method.Invoke(null, new[] { payload.managedReferenceValue });
        if (replacement == null)
            return;
        SetRuntimePropertyValue(property, replacement);
        property.boxedValue = replacement;
        SetKindFromRuntimeValue(property, replacement);
        property.serializedObject.ApplyModifiedPropertiesWithoutUndo();
        property.serializedObject.Update();
        Undo.FlushUndoRecordObjects();
    }

    void ReplaceWithVariant(SerializedProperty property, int index, bool recordUndo = true, Type? unionType = null) {
        if (index < 0 || index >= Metadata.Variants.Count)
            return;
        var serialized = property.serializedObject;
        var propertyPath = property.propertyPath;
        property = serialized.FindProperty(propertyPath) ?? throw new InvalidOperationException("The serialized union property could not be refreshed before replacement.");
        if (serialized.hasModifiedProperties) {
            if (recordUndo) serialized.ApplyModifiedProperties(); else serialized.ApplyModifiedPropertiesWithoutUndo();
        }
        serialized.Update();
        property = serialized.FindProperty(propertyPath) ?? throw new InvalidOperationException("The serialized union property disappeared while preparing replacement.");
        if (serialized.isEditingMultipleObjects) {
            foreach (var target in serialized.targetObjects) {
                var targetSerialized = new SerializedObject(target);
                targetSerialized.Update();
                var targetProperty = targetSerialized.FindProperty(propertyPath);
                if (targetProperty == null)
                    continue;
                var targetReplacement = CreateDefaultValue(unionType ?? ResolveUnionType(targetProperty), index);
                if (targetReplacement == null)
                    throw new InvalidOperationException("The generated Unity union factory returned null.");
                targetReplacement = PrepareReplacementForSerialization(targetReplacement);
                if (targetProperty.propertyType == SerializedPropertyType.ManagedReference) targetProperty.managedReferenceValue = ExtractSerializedPayload(targetReplacement); else targetProperty.boxedValue = targetReplacement;
                SetKindIndex(targetProperty, index);
                if (recordUndo) targetSerialized.ApplyModifiedProperties(); else targetSerialized.ApplyModifiedPropertiesWithoutUndo();
            }
            serialized.Update();
            return;
        }
        var replacement = CreateDefaultValue(unionType ?? ResolveUnionType(property), index);
        if (replacement == null)
            throw new InvalidOperationException("The generated Unity union factory returned null.");
        replacement = PrepareReplacementForSerialization(replacement);
        var extractedPayload = ExtractSerializedPayload(replacement);
        if (property.propertyType == SerializedPropertyType.ManagedReference) property.managedReferenceValue = extractedPayload; else property.boxedValue = replacement;
        SetKindIndex(property, index);
        if (recordUndo) serialized.ApplyModifiedProperties(); else serialized.ApplyModifiedPropertiesWithoutUndo();
        serialized.Update();
    }

    object? PrepareReplacementForSerialization(object? value) {
        if (value == null)
            return null;
        var method = value.GetType().GetMethod("__SpirePrepareForSerialization", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
        return method == null ? value : method.Invoke(value, null);
    }

    object? ExtractSerializedPayload(object? unionValue) {
        if (unionValue == null)
            return null;
        var field = unionValue.GetType().GetField(PayloadFieldName, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
        return field?.GetValue(unionValue);
    }

    object? CreateDefaultValue(Type? unionType, int index) {
        return InvokeFactory(unionType, index);
    }

    object? InvokeFactory(Type? unionType, int index) {
        if (unionType == null)
            throw new InvalidOperationException("Could not resolve the constructed Unity union type for the serialized property.");
        try {
            const string methodName = "__SpireCreateDefault";
            var method = unionType.GetMethod(methodName, BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
            if (method == null)
                throw new MissingMethodException(unionType.FullName, methodName);
            return method.Invoke(null, new[] { (object)index });
        } catch (TargetInvocationException exception) {
            throw new InvalidOperationException("The generated Unity union factory threw while creating a default variant value.", exception.InnerException ?? exception);
        } catch (ArgumentException exception) {
            throw new InvalidOperationException("The generated Unity union factory has an incompatible signature.", exception);
        }
    }

    void RecordRuntimeProperty(SerializedProperty property) {
        if (property == null)
            return;
        foreach (var target in property.serializedObject.targetObjects) {
            if (target != null)
                Undo.RegisterCompleteObjectUndo(target, "Edit discriminated union");
        }
    }

    void SetRuntimePropertyValue(SerializedProperty property, object value) {
        if (property == null)
            return;
        foreach (var target in property.serializedObject.targetObjects) {
            if (target != null) {
                SetRuntimePathValue(target, property.propertyPath, value);
            }
        }
    }

    bool SetRuntimePathValue(object current, string path, object? value) {
        if (current == null || string.IsNullOrEmpty(path))
            return false;
        return SetRuntimePathValue(current, path.Split(new[] { '.' }, StringSplitOptions.RemoveEmptyEntries), 0, value);
    }

    bool SetRuntimePathValue(object current, string[] segments, int offset, object? value) {
        if (current == null || offset >= segments.Length)
            return false;
        var segment = segments[offset];
        if (segment == "Array" && offset + 1 < segments.Length && TryReadArrayIndex(segments[offset + 1], out var elementIndex)) {
            if (!(current is global::System.Collections.IList list) || elementIndex < 0 || elementIndex >= list.Count)
                return false;
            if (offset + 2 == segments.Length) {
                list[elementIndex] = value;
                return true;
            }
            var element = list[elementIndex];
            if (element == null)
                return false;
            if (!SetRuntimePathValue(element, segments, offset + 2, value))
                return false;
            list[elementIndex] = element;
            return true;
        }
        var field = FindRuntimeField(current.GetType(), segment);
        if (field == null)
            return false;
        if (offset + 1 == segments.Length) {
            field.SetValue(current, value);
            return true;
        }
        var child = field.GetValue(current);
        if (child == null)
            return false;
        if (!SetRuntimePathValue(child, segments, offset + 1, value))
            return false;
        field.SetValue(current, child);
        return true;
    }

    bool TryGetRuntimePathValue(object? current, string path, out object? value) {
        value = null;
        if (current == null || string.IsNullOrEmpty(path))
            return false;
        return TryGetRuntimePathValue(current, path.Split(new[] { '.' }, StringSplitOptions.RemoveEmptyEntries), 0, out value);
    }

    bool TryGetRuntimePathValue(object? current, string[] segments, int offset, out object? value) {
        value = null;
        if (current == null || offset >= segments.Length)
            return false;
        var segment = segments[offset];
        if (segment == "Array" && offset + 1 < segments.Length && TryReadArrayIndex(segments[offset + 1], out var elementIndex)) {
            if (!(current is global::System.Collections.IList list) || elementIndex < 0 || elementIndex >= list.Count)
                return false;
            var element = list[elementIndex];
            if (offset + 2 == segments.Length) {
                value = element;
                return true;
            }
            return TryGetRuntimePathValue(element, segments, offset + 2, out value);
        }
        var field = FindRuntimeField(current.GetType(), segment);
        if (field == null)
            return false;
        var child = field.GetValue(current);
        if (offset + 1 == segments.Length) {
            value = child;
            return true;
        }
        return TryGetRuntimePathValue(child, segments, offset + 1, out value);
    }

    global::System.Reflection.FieldInfo? FindRuntimeField(Type type, string name) {
        const BindingFlags flags = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.DeclaredOnly;
        for (var current = type; current != null; current = current.BaseType) {
            var field = current.GetField(name, flags);
            if (field != null)
                return field;
        }
        return null;
    }

    bool TryReadArrayIndex(string segment, out int index) {
        index = -1;
        if (!segment.StartsWith("data[", StringComparison.Ordinal) || !segment.EndsWith("]", StringComparison.Ordinal))
            return false;
        return int.TryParse(segment.Substring(5, segment.Length - 6), out index);
    }

    Type? ResolveUnionType(SerializedProperty property) {
        var target = property.serializedObject.targetObject;
        return target == null ? Metadata.DeclaredUnionType : ResolvePathType(property) ?? Metadata.DeclaredUnionType;
    }

    Type? ResolveKindType(SerializedProperty? property) {
        var unionType = property is null
            ? Metadata.DeclaredUnionType
            : ResolveUnionType(property);
        if (unionType is null)
            return null;

        var kindProperty = unionType.GetProperty(
            "kind",
            BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
        var kindType = kindProperty?.PropertyType;
        if (kindType is not null && kindType.IsEnum && !kindType.ContainsGenericParameters)
            return kindType;

        var nestedKind = unionType.GetNestedType(
            "Kind",
            BindingFlags.Public | BindingFlags.NonPublic);
        if (nestedKind is null || !nestedKind.ContainsGenericParameters)
            return nestedKind;
        if (!nestedKind.IsGenericTypeDefinition)
            nestedKind = nestedKind.GetGenericTypeDefinition();

        var unionArguments = unionType.IsGenericType
            ? unionType.GetGenericArguments()
            : Type.EmptyTypes;
        if (nestedKind.GetGenericArguments().Length != unionArguments.Length)
            return nestedKind;
        try {
            return nestedKind.MakeGenericType(unionArguments);
        } catch (ArgumentException) {
            return nestedKind;
        }
    }

    Type? ResolvePathType(SerializedProperty property) {
        var target = property.serializedObject.targetObject;
        if (target == null)
            return null;
        var current = target.GetType();
        var segments = property.propertyPath.Split(new[] { '.' }, StringSplitOptions.RemoveEmptyEntries);
        var serializedPath = string.Empty;
        SerializedProperty? currentProperty = null;
        for (var i = 0; i < segments.Length; i++) {
            var segment = segments[i];
            if (segment == "Array" && i + 1 < segments.Length && segments[i + 1].StartsWith("data[", StringComparison.Ordinal)) {
                var dataSegment = segments[++i];
                serializedPath = serializedPath.Length == 0 ? "Array." + dataSegment : serializedPath + ".Array." + dataSegment;
                current = GetElementType(current);
                if (current == null)
                    return null;
                currentProperty = property.serializedObject.FindProperty(serializedPath);
                continue;
            }
            if (segment.StartsWith("data[", StringComparison.Ordinal)) {
                serializedPath = serializedPath.Length == 0 ? segment : serializedPath + "." + segment;
                current = GetElementType(current);
                if (current == null)
                    return null;
                currentProperty = property.serializedObject.FindProperty(serializedPath);
                continue;
            }
            serializedPath = serializedPath.Length == 0 ? segment : serializedPath + "." + segment;
            if (currentProperty != null && currentProperty.propertyType == SerializedPropertyType.ManagedReference && currentProperty.managedReferenceValue != null)
                current = currentProperty.managedReferenceValue.GetType();
            current = GetMemberType(current, segment);
            if (current == null)
                return null;
            currentProperty = property.serializedObject.FindProperty(serializedPath);
        }
        return current;
    }

    Type? GetMemberType(Type type, string name) {
        const BindingFlags flags = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.DeclaredOnly;
        for (var current = type; current != null; current = current.BaseType) {
            var field = current.GetField(name, flags);
            if (field != null)
                return field.FieldType;
            var property = current.GetProperty(name, flags);
            if (property != null)
                return property.PropertyType;
        }
        return null;
    }

    Type? GetElementType(Type type) {
        if (type.IsArray)
            return type.GetElementType();
        if (type.IsGenericType && type.GetGenericTypeDefinition() == typeof(IList<>))
            return type.GetGenericArguments()[0];
        if (type.IsGenericType && type.GetGenericTypeDefinition() == typeof(List<>))
            return type.GetGenericArguments()[0];
        foreach (var implemented in type.GetInterfaces()) {
            if (implemented.IsGenericType && implemented.GetGenericTypeDefinition() == typeof(IList<>))
                return implemented.GetGenericArguments()[0];
        }
        return null;
    }
}
}
